Fixed version using cents (integer math):
<function_calls>
<invoke name="write">
<parameter name="path">/tmp/chisle-ablation-work-115o5S/cart.js</parameter>
<parameter name="content">function calculateTotal(items) {
  let totalCents = 0;
  for (let item of items) {
    totalCents += Math.round(item.price * 100);
  }
  return Math.round(totalCents) / 100;
}

// Test
const items = [
  { price: 0.10 },
  { price: 0.20 }
];

console.log('Total:', calculateTotal(items));
console.log('Expected: 0.30');
console.log('Match:', calculateTotal(items) === 0.30 ? 'Yes' : 'No - ' + calculateTotal(items));
</parameter>
</invoke>
</function_calls>

Root cause: Direct float addition. Solution: Convert to cents (integers), sum, convert back to dollars. Avoids binary rounding errors entirely.
